## ✅ Recommended: Use a Proper Secrets Manager

Here's how to refactor this properly:

### Option A: AWS Secrets Manager (Recommended for AWS)

```javascript
// app.js - Using AWS Secrets Manager
const AWS = require('aws-sdk');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretManager {
  constructor() {
    this.client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1' 
    });
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTimeout) {
        return cached.value;
      }
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secret;
      if ('SecretString' in response) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = JSON.parse(Buffer.from(response.SecretBinary, 'base64').toString());
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Error fetching secret ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }
}

const secrets = new SecretManager();

// Initialize app with secrets
async function initializeApp() {
  try {
    const dbSecret = await secrets.getSecret('prod/database/url');
    const apiSecrets = await secrets.getSecret('prod/api/keys');

    // Use secrets in configuration
    const dbConfig = {
      connectionString: dbSecret.url,
      ssl: { rejectUnauthorized: true }
    };

    console.log('Secrets loaded successfully');
    return { dbConfig, apiSecrets };
  } catch (error) {
    console.error('Failed to initialize application:', error);
    process.exit(1);
  }
}

module.exports = { app, initializeApp, secrets };
```

**AWS Secrets Manager Setup:**
```bash
# Store secrets using AWS CLI
aws secretsmanager create-secret \
  --name prod/database/url \
  --secret-string '{"url":"postgres://...","username":"...","password":"..."}'

aws secretsmanager create-secret \
  --name prod/api/keys \
  --secret-string '{"anthropic":"sk-ant-...","stripe":"sk_live_..."}'

# Enable automatic rotation
