### Option B: HashiCorp Vault

```javascript
// app.js - Using HashiCorp Vault
const nodeVault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
  token: process.env.VAULT_TOKEN // Only this token from env, rotate regularly
});

class VaultSecretManager {
  async getSecret(path, key) {
    try {
      const result = await nodeVault.read(`secret/data/${path}`);
      return result.data.data[key];
    } catch (error) {
      console.error(`Vault error for ${path}:`, error.message);
      throw error;
    }
  }

  async getDatabaseConfig() {
    const [host, port, username, password] = await Promise.all([
      this.getSecret('database/prod', 'host'),
      this.getSecret('database/prod', 'port'),
      this.getSecret('database/prod', 'username'),
      this.getSecret('database/prod', 'password')
    ]);

    return { host, port, username, password };
  }
}

const vault = new VaultSecretManager();
```

