```javascript
// config/secrets.js
class SecretsConfig {
  constructor() {
    this.secrets = {};
    this.loadMethod = this.detectEnvironment();
  }

  detectEnvironment() {
    if (process.env.AWS_SECRET_ID) return 'aws';
    if (process.env.VAULT_ADDR) return 'vault';
    if (process.env.NODE_ENV === 'production') return 'env';
    return 'local'; // Development only
  }

  async load() {
    switch (this.loadMethod) {
      case 'aws':
        return this.loadFromAWS();
      case 'vault':
        return this.loadFromVault();
      case 'env':
        return this.loadFromEnv();
      case 'local':
        return this.loadFromLocal();
      default:
        throw new Error('Unknown secrets backend');
    }
  }

  async loadFromAWS() {
    const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
    const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

    const secretId = process.env.AWS_SECRET_ID;
    const command = new GetSecretValueCommand({ SecretId: secretId });
    const response = await client.send(command);

    this.secrets = JSON.parse(response.SecretString);
    return this.secrets;
  }

  async loadFromEnv() {
    // Validate all required secrets are present
    const required = ['DATABASE_URL', 'ANTHROPIC_API_KEY'];
    const missing = required.filter(key => !process.env[key]);

    if (missing.length > 0) {
      throw new Error(`Missing secrets: ${missing.join(', ')}`);
    }

    this.secrets = {
      database: { url: process.env.DATABASE_URL },
      api: {
        anthropic: process.env.ANTHROPIC_API_KEY,
        stripe: process.env.STRIPE_SECRET_KEY
      }
    };

    return this.secrets;
  }

  async loadFromLocal() {
    console.warn('⚠️  Using local .env file - NOT FOR PRODUCTION');
    require('dotenv').config();
    return this.loadFromEnv();
  }

  get(key) {
    if (!this.secrets[key]) {
      throw new Error(`Secret not found: ${key}`);
    }
    return this.secrets[key];
  }
}

module.exports = new SecretsConfig();
```

