const AWS = require('aws-sdk');
const ssm = new AWS.SSM();

class SecretsManager {
  async loadSecrets() {
    try {
      // Load from AWS Parameter Store or Secrets Manager at runtime
      const params = {
        Names: [
          '/app/database/url',
          '/app/aws/access-key-id',
          '/app/aws/secret-access-key',
          '/app/stripe/secret-key'
        ],
        WithDecryption: true
      };

      const result = await ssm.getParameters(params).promise();

      return result.Parameters.reduce((acc, param) => {
        const key = param.Name.split('/').pop().toUpperCase().replace('-', '_');
        acc[key] = param.Value;
        return acc;
      }, {});

