### 3. **Secrets Rotation Hook**

```javascript
const crypto = require('crypto');

class SecretRotator {
  constructor(secretsManager, secretId) {
    this.secretsManager = secretsManager;
    this.secretId = secretId;
  }

  async rotateSecret() {
    const currentSecret = await this.getSecret();
    const newSecret = this.generateSecret();

    await this.secretsManager.putSecretValue({
      SecretId: this.secretId,
      SecretString: JSON.stringify(currentSecret),
      VersionStages: ['AWSPREVIOUS']
    }).promise();

    await this.secretsManager.putSecretValue({
      SecretId: this.secretId,
      SecretString: JSON.stringify({ secret: newSecret }),
      VersionStages: ['AWSCURRENT']
    }).promise();

    return newSecret;
  }

  generateSecret() {
    return crypto.randomBytes(64).toString('hex');
  }
}
```

