    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

// ==================== PROTECTED ROUTES ====================
// In a real app, these would use proper authentication
const mockAuthenticate = (req, res, next) => {
  // TODO: Implement JWT authentication
  // For now, this is a placeholder
  next();
};

app.get(
  '/api/users',
  strictLimiter,
