## Option B: HashiCorp Vault

### Setup
```javascript
// config/vault.js
const axios = require('axios');

const VAULT_ADDR = process.env.VAULT_ADDR || 'https://vault.example.com:8200';
const VAULT_ROLE = process.env.VAULT_ROLE || 'myapp';

let vaultToken = null;

// Get Vault token from AWS IAM or Kubernetes auth
const getVaultToken = async () => {
  if (vaultToken && isTokenValid(vaultToken)) {
    return vaultToken;
  }

  const response = await axios.post(
    `${VAULT_ADDR}/v1/auth/aws/login`,
    { role: VAULT_ROLE },
    { headers: { 'X-Vault-Namespace': process.env.VAULT_NAMESPACE } }
  );

  vaultToken = response.data.auth.client_token;
  return vaultToken;
};

const getSecret = async (path) => {
  const token = await getVaultToken();

  const response = await axios.get(
    `${VAULT_ADDR}/v1/${path}`,
    {
      headers: {
        'X-Vault-Token': token,
        'X-Vault-Namespace': process.env.VAULT_NAMESPACE
      }
    }
  );

  return response.data.data.data;
};

module.exports = { getSecret };
```

