### Secure loading pattern
```javascript
// config/env.js
const path = require('path');
const dotenv = require('dotenv');

// Determine environment
const NODE_ENV = process.env.NODE_ENV || 'development';

// Only load .env files in non-production
if (NODE_ENV !== 'production') {
  const envFile = `.env${NODE_ENV !== 'production' ? `.${NODE_ENV}` : ''}`;
  const envPath = path.resolve(process.cwd(), envFile);

  try {
    const result = dotenv.config({ path: envPath });

    if (result.error) {
      if (NODE_ENV === 'test') {
        // Test environment can use defaults
        console.warn(`Warning: No ${envFile} found, using defaults`);
      } else {
        throw result.error;
      }
    }

    console.log(`Loaded environment from ${envFile}`);
  } catch (error) {
    console.error('Failed to load environment file:', error.message);
    process.exit(1);
  }
} else {
  // Production: require ALL secrets to be in environment
  const requiredSecrets = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'STRIPE_SECRET_KEY'
  ];

  const missing = requiredSecrets.filter(key => !process.env[key]);

  if (missing.length > 0) {
    console.error(`Missing required secrets: ${missing.join(', ')}`);
    process.exit(1);
  }
}

// Export typed config object with validation
const config = {
  env: {
    node: NODE_ENV,
    isProduction: NODE_ENV === 'production',
    isTest: NODE_ENV === 'test',
    isDevelopment: NODE_ENV === 'development',
  },
  database: {
    url: process.env.DATABASE_URL,
  },
  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    region: process.env.AWS_REGION || 'us-east-1',
  },
  stripe: {
    secretKey: process.env.STRIPE_SECRET_KEY,
  },
  // Validate at startup
  validate() {
    const errors = [];

    if (!this.database.url) errors.push('DATABASE_URL required');
    if (!this.aws.accessKeyId) errors.push('AWS_ACCESS_KEY_ID required');
    if (!this.aws.secretAccessKey) errors.push('AWS_SECRET_ACCESS_KEY required');

    if (errors.length > 0) {
      throw new Error(`Invalid configuration: ${errors.join(', ')}`);
    }
  }
};

// Immediate validation in production
if (config.env.isProduction) {
  config.validate();
}

module.exports = config;
```

