### 3. Input Validation and Sanitization

#### Vulnerability
No input validation allows injection attacks.

#### Remediation Code
```javascript
const { body, param, validationResult } = require('express-validator');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');

// Sanitization middleware
app.use(express.json({ limit: '10kb' }));
app.use(mongoSanitize());
app.use(xss());

// Validation middleware
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      message: 'Validation failed',
      errors: errors.array()
    });
  }
  next();
};

// Example protected route
app.get(
  '/users/:id',
  param('id').isInt({ min: 1 }).withMessage('Valid ID required'),
  validate,
  async (req, res) => {
    const user = await User.findById(req.params.id);
    res.json({ success: true, data: user });
  }
);
```

---

### 4. Authentication and Authorization

#### Vulnerability
No authentication allows unauthorized access to user data.

#### Remediation Code
```javascript
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

// Authentication middleware
const authenticate = async (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader?.startsWith('Bearer ')) {
      return res.status(401).json({
        success: false,
        message: 'Authentication required'
      });
    }

    const token = authHeader.split(' ')[1];
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(401).json({
      success: false,
      message: 'Invalid or expired token'
    });
  }
};

// Authorization middleware (role-based)
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!roles.includes(req.user.role)) {
      return res.status(403).json({
        success: false,
        message: 'Access denied'
      });
    }
    next();
  };
};

// Protected endpoint
app.get('/users', authenticate, authorize('admin'), async (req, res) => {
  const users = await User.find({}, '-password');
  res.json({ success: true, data: users });
});
```

---

### 5. Error Handling (Prevent Information Disclosure)

#### Vulnerability
Poor error handling can leak sensitive information.

#### Remediation Code
```javascript
// Centralized error handler
app.use((err, req, res, next) => {
  // Log without sensitive data
  console.error('Error:', {
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.statusCode || 500).json({
    success: false,
    message: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    message: 'Resource not found'
  });
});
```

