```javascript
// config/index.js
require('dotenv-safe').config(); // Only in non-production environments

const missingVars = [];

const getRequired = (name) => {
  const value = process.env[name];
  if (!value) missingVars.push(name);
  return value;
};

const getOptional = (name, defaultValue = undefined) => {
  return process.env[name] || defaultValue;
};

const config = {
  // App
  nodeEnv: getOptional('NODE_ENV', 'development'),
  port: getOptional('PORT', 3000),

  // Database - parse connection string for security
  database: {
    host: getRequired('DB_HOST'),
    port: getOptional('DB_PORT', 5432),
    database: getRequired('DB_NAME'),
    user: getRequired('DB_USER'),
    password: getRequired('DB_PASSWORD'), // Secure, separate from connection string
    ssl: getOptional('DB_SSL', 'true') === 'true'
  },

  // AWS
  aws: {
    region: getOptional('AWS_REGION', 'us-east-1'),
    accessKeyId: getRequired('AWS_ACCESS_KEY_ID'),
    secretAccessKey: getRequired('AWS_SECRET_ACCESS_KEY')
  },

  // API keys
  anthropicApiKey: getRequired('ANTHROPIC_API_KEY'),
  stripeSecretKey: getRequired('STRIPE_SECRET_KEY'),
  logfireToken: getRequired('LOGFIRE_TOKEN')
};

// Validate at startup
if (missingVars.length > 0) {
  throw new Error(
    `Missing required environment variables: ${missingVars.join(', ')}`
  );
}

module.exports = config;
```

