## ✅ Recommended Secret Management Solutions

Here are three approaches, ordered from most secure to least secure:

### **Option 1: Production-Grade Secrets Manager (Recommended)**

Use AWS Secrets Manager, HashiCorp Vault, or Azure Key Vault:

```javascript
// config/secrets.js
const AWS = require('aws-sdk');

// Initialize Secrets Manager client
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1',
});

// Secret cache to avoid repeated API calls
let secretsCache = null;

/**
 * Fetch secrets from AWS Secrets Manager
 * Secret structure in AWS:
 * {
 *   "DATABASE_URL": "...",
 *   "JWT_SECRET": "...",
 *   "STRIPE_SECRET_KEY": "..."
 * }
 */
async function getSecrets() {
  if (secretsCache) {
    return secretsCache;
  }

  try {
    const secretId = process.env.SECRETS_MANAGER_ARN || `production/${process.env.NODE_ENV}/app`;

    const data = await secretsManager.getSecretValue({ SecretId: secretId }).promise();

    if ('SecretString' in data) {
      secretsCache = JSON.parse(data.SecretString);
    } else {
      secretsCache = JSON.parse(Buffer.from(data.SecretBinary, 'base64').toString());
    }

    // Auto-rotate: don't cache indefinitely
    setTimeout(() => { secretsCache = null; }, 5 * 60 * 1000); // 5 minutes

    return secretsCache;
  } catch (error) {
    console.error('❌ Failed to fetch secrets:', error.message);
    throw new Error('Unable to load application secrets');
  }
}

module.exports = { getSecrets };
```

