### **Option 3: Encrypted .env Files (Least Secure but Better Than Plain Text)**

If you must use .env files, encrypt them:

```javascript
// config/encrypted-env.js
const crypto = require('crypto');
const fs = require('fs');

// Generate encryption key (run once)
function generateKey() {
  return crypto.randomBytes(32).toString('hex');
}

// Encrypt .env file
function encryptEnv(inputPath, outputPath, keyHex) {
  const key = Buffer.from(keyHex, 'hex');
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);

  const content = fs.readFileSync(inputPath, 'utf8');
  let encrypted = cipher.update(content, 'utf8', 'hex');
  encrypted += cipher.final('hex');

  const authTag = cipher.getAuthTag();

  const output = JSON.stringify({
    iv: iv.toString('hex'),
    authTag: authTag.toString('hex'),
    data: encrypted,
  });

  fs.writeFileSync(outputPath, output, 'utf8');
}

// Decrypt .env file at runtime
function decryptEnv(encryptedPath, keyHex) {
  try {
    const key = Buffer.from(keyHex, 'hex');
    const encrypted = JSON.parse(fs.readFileSync(encryptedPath, 'utf8'));

    const iv = Buffer.from(encrypted.iv, 'hex');
    const authTag = Buffer.from(encrypted.authTag, 'hex');
    const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
    decipher.setAuthTag(authTag);

    let decrypted = decipher.update(encrypted.data, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    // Parse key=value pairs
    const envVars = {};
    decrypted.split('\n').forEach(line => {
      const [key, ...values] = line.split('=');
      if (key && !key.startsWith('#')) {
        envVars[key.trim()] = values.join('=').trim();
      }
    });

    return envVars;
  } catch (error) {
    console.error('❌ Failed to decrypt environment file:', error.message);
    throw error;
  }
}

module.exports = { generateKey, encryptEnv, decryptEnv };
```

