      status, // pending, in-progress, rotated, verified, failed
      notes,
      lastUpdated: new Date().toISOString(),
    });
  }

  updateStatus(variable, status, notes = '') {
    const cred = this.credentials.find(c => c.variable === variable);
    if (cred) {
      cred.status = status;
      cred.notes = notes;
      cred.lastUpdated = new Date().toISOString();
    }
  }

  generateReport(format = 'markdown') {
    if (format === 'markdown') {
      return this._generateMarkdown();
    } else if (format === 'csv') {
      return this._generateCSV();
    } else if (format === 'json') {
      return this._generateJSON();
    }
  }

  _generateMarkdown() {
    let output = '# Credential Rotation Report\n\n';
    output += `Generated: ${new Date().toISOString()}\n\n`;
    output += '| Variable | Service | Status | Notes |\n';
    output += '|----------|---------|--------|-------|\n';

    this.credentials.forEach(cred => {
      const statusIcon = {
        'pending': '⏳',
        'in-progress': '🔄',
        'rotated': '✅',
        'verified': '✨',
        'failed': '❌',
      }[cred.status] || '❓';

      output += `| ${cred.variable} | ${cred.service} | ${statusIcon} ${cred.status} | ${cred.notes} |\n`;
    });

    return output;
  }

  _generateCSV() {
    let output = 'variable,service,status,lastUpdated,notes\n';
    this.credentials.forEach(cred => {
      output += `"${cred.variable}","${cred.service}","${cred.status}","${cred.lastUpdated}","${cred.notes}"\n`;
    });
    return output;
  }

  _generateJSON() {
    return JSON.stringify({
      generatedAt: new Date().toISOString(),
      credentials: this.credentials,
    }, null, 2);
  }
}

