/**
 * Secure Express.js Application
 * This file demonstrates security best practices
 */
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const winston = require('winston');
const { body, query, param, validationResult } = require('express-validator');
const passport = require('passport');
const { Strategy: JwtStrategy, ExtractJwt } = require('passport-jwt');
const timeout = require('connect-timeout');

// ============================================================================
// ENVIRONMENT VALIDATION
// ============================================================================
const requiredEnvVars = [
  'NODE_ENV',
  'JWT_SECRET'
];

const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);
if (missingVars.length > 0) {
  throw new Error(`Missing required environment variables: ${missingVars.join(', ')}`);
}

// ============================================================================
// LOGGING CONFIGURATION
// ============================================================================
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'secure-api' },
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// ============================================================================
// EXPRESS CONFIGURATION
// ============================================================================
const app = express();

// Trust proxy (for rate limiting behind reverse proxy)
app.set('trust proxy', 1);

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Helmet - Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  frameguard: { action: 'deny' },
  xssFilter: true
}));

// CORS Configuration
const allowedOrigins = (process.env.ALLOWED_ORIGINS || '').split(',').filter(Boolean);
app.use(cors({
  origin: (origin, callback) => {
    if (!origin) return callback(null, true);
    if (allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn('CORS violation attempt', { origin });
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400
}));

// Rate Limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn('Rate limit exceeded', {
      ip: req.ip,
      path: req.path,
      method: req.method
    });
    res.status(429).json({ error: 'Too many requests, please try again later.' });
  }
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Too many attempts, please try again later.' },
  skipSuccessfulRequests: true
});

app.use('/api/', generalLimiter);

// Request Timeout
app.use(timeout('30s'));

// Body Parser with Limits
app.use(express.json({
  limit: '10kb',
  strict: true
}));
app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// Request Logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim())
  }
}));

// ============================================================================
// AUTHENTICATION
// ============================================================================

// JWT Strategy
const jwtOptions = {
  jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
  secretOrKey: process.env.JWT_SECRET,
  issuer: process.env.JWT_ISSUER || 'your-domain.com',
  audience: process.env.JWT_AUDIENCE || 'your-domain.com'
};

passport.use(new JwtStrategy(jwtOptions, async (payload, done) => {
  try {
    // Verify user from database
    // const user = await User.findById(payload.sub);
    // if (!user) return done(null, false);
    // return done(null, user);

    // Mock implementation
    if (payload.sub && payload.role) {
      return done(null, { id: payload.sub, role: payload.role });
    }
    return done(null, false);
  } catch (error) {
    return done(error, false);
  }
}));

app.use(passport.initialize());

// Auth middleware helper
const requireAuth = (roles = []) => {
  return (req, res, next) => {
    passport.authenticate('jwt', { session: false }, (err, user, info) => {
      if (err) {
        logger.error('Auth error', { error: err.message });
        return res.status(500).json({ error: 'Authentication error' });
      }
      if (!user) {
        logger.warn('Unauthenticated request', {
          ip: req.ip,
          path: req.path
        });
        return res.status(401).json({ error: 'Unauthorized' });
      }
      if (roles.length > 0 && !roles.includes(user.role)) {
        logger.warn('Unauthorized role attempt', {
          ip: req.ip,
          path: req.path,
          userRole: user.role,
          requiredRoles: roles
        });
        return res.status(403).json({ error: 'Forbidden' });
      }

      req.user = user;
      return next();
    })(req, res, next);
  };
};

// ============================================================================
// INPUT VALIDATION HELPERS
// ============================================================================

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation errors', {
      ip: req.ip,
      path: req.path,
      errors: errors.array()
    });
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// ============================================================================
// SANITIZATION HELPER
// ============================================================================

const sanitizeUserData = (user) => {
  const { id, name, email, ...sensitiveData } = user;

  // Only return non-sensitive data
  const result = { id, name };

  // Include email only for admins or the user themselves
  // This would be handled based on req.user in a real app
  if (process.env.INCLUDE_EMAIL_IN_RESPONSES === 'true') {
    result.email = email;
  }

  return result;
};

// ============================================================================
// ROUTES
// ============================================================================

// Health check - no authentication required
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0',
    environment: process.env.NODE_ENV
  });
});

// Get users - requires authentication
app.get('/users', 
  requireAuth(['admin', 'user']),
  handleValidationErrors,
  (req, res) => {
    try {
      logger.info('Users endpoint accessed', {
        userId: req.user.id,
        userRole: req.user.role,
        ip: req.ip
      });

      // Mock user data - in production, fetch from database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Sanitize user data before sending
      const sanitizedUsers = users.map(sanitizeUserData);

      res.json(sanitizedUsers);
    } catch (error) {
      logger.error('Error fetching users', {
        error: error.message,
        stack: error.stack,
        userId: req.user?.id
      });
      res.status(500).json({ error: 'Internal Server Error' });
    }
  }
);

// Get specific user - requires authentication + validation
app.get('/users/:id',
  requireAuth(['admin', 'user']),
  param('id').isInt({ min: 1, max: 1000000 }),
  handleValidationErrors,
  (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      logger.info('User detail accessed', {
        requestedUserId: userId,
        requestingUserId: req.user.id,
        requestingUserRole: req.user.role,
        ip: req.ip
      });

      // Authorization: users can only see their own data unless admin
      if (req.user.role !== 'admin' && req.user.id !== userId) {
        logger.warn('Unauthorized user access attempt', {
          requestingUserId: req.user.id,
          requestedUserId: userId
        });
        return res.status(403).json({ error: 'Forbidden' });
      }

      // Mock user data
      const user = { id: userId, name: 'Alice', email: 'alice@example.com' };

      // Return full data for admin viewing own/others, or user viewing themselves
      if (req.user.role === 'admin' || req.user.id === userId) {
        // For admins, return more data
        if (req.user.role === 'admin') {
          return res.json(user);
        }
        // Regular users get sanitized data
        return res.json(sanitizeUserData(user));
      }

      res.status(404).json({ error: 'User not found' });
    } catch (error) {
      logger.error('Error fetching user', {
        error: error.message,
        userId: req.params.id
      });
      res.status(500).json({ error: 'Internal Server Error' });
    }
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

// Handle timeout errors
app.use((req, res, next) => {
  if (!req.timedout) next();
  else {
    logger.warn('Request timeout', {
      ip: req.ip,
      path: req.path,
      method: req.method
    });
    res.status(504).json({ error: 'Request timeout' });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  // Log full error
  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    ip: req.ip,
    path: req.path,
    method: req.method,
    userId: req.user?.id
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// 404 handler
app.use((req, res) => {
  logger.warn('404 Not Found', {
    ip: req.ip,
    path: req.path,
    method: req.method
  });
  res.status(404).json({ error: 'Not Found' });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`, {
    environment: process.env.NODE_ENV,
    port: PORT,
    timestamp: new Date().toISOString()
  });
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  logger.info(`${signal} received, starting graceful shutdown`);

  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    logger.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception', {
    error: error.message,
    stack: error.stack
  });
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection', {
    reason,
    promise
  });
  process.exit(1);
});

module.exports = app;

