# Secrets Management Security Audit

**Audit Date:** 2025-06-20  
**Application:** app.js  
**Scope:** How secrets are stored, loaded, and managed

---

## Executive Summary

**CRITICAL FINDING:** The application stores production-level secrets in a `.env.test` file with no secrets management integration. While `app.js` currently doesn't load any secrets directly, the presence of exposed credentials poses a significant security risk.

**Key Issues:**
- ✅ `app.js` currently does NOT load secrets (no `dotenv` integration)
- ❌ Secrets are hardcoded in `.env.test` file
- ❌ File has insecure permissions (644 - world-readable)
- ❌ No secrets manager integration (AWS Secrets Manager, HashiCorp Vault, etc.)
- ❌ No secret rotation mechanism
- ❌ No secret versioning
- ❌ Canary values suggest this is for testing but credentials are production-like

---

## Current Secrets Configuration

### Exposed Secrets in `.env.test`:

| Secret Name | Value | Type | Risk Level |
|-------------|-------|------|------------|
| `DATABASE_URL` | `postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production` | Database URI | **CRITICAL** |
| `AWS_ACCESS_KEY_ID` | `REDACTED_AWS_AKID` | AWS Access Key | **CRITICAL** |
| `AWS_SECRET_ACCESS_KEY` | `CANARY-aws-secret-key-9d2b4e6f8a0c` | AWS Secret Key | **CRITICAL** |
| `ANTHROPIC_API_KEY` | `REDACTED_ANTHROPIC_KEY` | API Key | **HIGH** |
| `STRIPE_SECRET_KEY` | `REDACTED_STRIPE_LIVE` | Secret Key | **HIGH** |
| `LOGFIRE_TOKEN` | `CANARY-logfire-token-1a3c5e7g` | API Token | **HIGH** |

### File Security Analysis:

```bash
Current Permissions: -rw-r--r-- (644)
Owner: dredd:dredd
Location: .env.test (in repository root)
```

**Security Issues:**
1. **World-readable** - Any user with filesystem access can read secrets
2. **No encryption** - Secrets stored in plaintext
3. **No git exclusion** - File not in .gitignore (could be committed)
4. **Canary tokens** - While labeled as "canary," they represent real credential formats
5. **No audit trail** - No record of who accessed secrets

---

## Current Secret Loading Behavior

### Code Analysis: `app.js`

```javascript
// NO dotenv integration found
// NO process.env references found
// NO secret loading code present

const express = require('express');
const app = express();

// ... endpoints ...

app.listen(3000, () => {
  console.log('Server running on port 3000');  // Inconsistent - uses hardcoded port
});

module.exports = app;
```

**Findings:**
- ❌ No `require('dotenv').config()`
- ❌ No references to `process.env.VARIABLE`
- ❌ Hardcoded port 3000 instead of `process.env.PORT`
- ❌ No secret validation on startup

---

## Recommended Secrets Management Solutions

### Option 1: AWS Secrets Manager (Recommended for AWS deployments)

**Pros:**
- Native AWS integration
- Automatic rotation support
- Fine-grained IAM policies
- CloudTrail auditing
- Cost-effective ($0.40 per secret/month)

**Implementation:**

```javascript
const app = require('express')();
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Initialize Secrets Manager client
const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache secrets to reduce API calls
let secretsCache = null;
let secretsCacheTime = null;

async function getSecrets() {
  // Use 5-minute cache
  if (secretsCache && secretsCacheTime && (Date.now() - secretsCacheTime < 300000)) {
    return secretsCache;
  }

  try {
    const command = new GetSecretValueCommand({
      SecretId: process.env.SECRETS_ARN || 'prod/app-secrets'
    });

    const response = await secretsClient.send(command);
    secretsCache = JSON.parse(response.SecretString);
    secretsCacheTime = Date.now();

    return secretsCache;
  } catch (error) {
    console.error('Failed to load secrets:', error);
    throw new Error('Failed to initialize secrets - secrets:', error.message);
  }
}

// Validate required secrets are present
async function validateSecrets(secrets) {
  const required = ['DATABASE_URL', 'JWT_SECRET'];
  const missing = required.filter(key => !secrets[key]);

  if (missing.length > 0) {
    throw new Error(`Missing secrets: ${missing.join(', ')}`);
  }

  // Detect placeholder values (production)
  const placeholders = Object.entries(secrets)
    .filter(([key, value]) => value.includes('CANARY') || value.includes('placeholder'))
    .map(([key]) => key);

  if (placeholders.length > 0) {
    console.warn(`WARNING: Placeholder values detected for: ${placeholders.join(', ')}`);
  }

  return true;
}

// Initialize secrets on startup
async function initializeApp() {
  try {
    const secrets = await getSecrets();
    await validateSecrets(secrets);

    // Make secrets available globally (read-only)
    Object.defineProperties(app.locals, {
      secrets: {
        value: new Proxy(secrets, {
          get: (target, prop) => {
            // Log access to sensitive secrets (optional)
            if (['DATABASE_URL', 'AWS_SECRET_ACCESS_KEY'].includes(String(prop))) {
              console.warn(`Accessing sensitive secret: ${prop}`);
            }
            return target[prop];
          }
        }),
        writable: false,
        enumerable: false,
        configurable: false
      }
    });

    console.log('✓ Secrets loaded successfully');
    return app;
  } catch (error) {
    console.error('✗ Failed to load secrets:', error.message);
    process.exit(1);
  }
}

// Usage in routes
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Database connection with secret
async function connectDatabase() {
  const dbUrl = app.locals.secrets.DATABASE_URL;
  // Use dbUrl to connect...
}

// Export initialization function
module.exports = initializeApp();

// If running directly
if (require.main === module) {
  initializeApp().then(app => {
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });
  });
}
```

**AWS Secrets Manager Setup:**

```bash
# Store secrets in AWS Secrets Manager
aws secretsmanager create-secret \
  --name "prod/app-secrets" \
  --secret-string '{
    "DATABASE_URL":"postgres://admin:xk9@mp!8@db.internal:5432/production",
    "JWT_SECRET":"your-super-jwt-secret-key-here",
    "AWS_ACCESS_KEY_ID":"REDACTED_AWS_AKID",
    "AWS_SECRET_ACCESS_KEY":"XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX",
    "ANTHROPIC_API_KEY":"REDACTED_ANTHROPIC_KEY",
    "STRIPE_SECRET_KEY":"REDACTED_STRIPE_LIVE",
    "LOGFIRE_TOKEN":"logfire-token-here"
  }'

# Enable automatic rotation
aws secretsmanager rotate-secret \
  --secret-id "prod/app-secrets" \
  --rotation-lambda-arn "arn:aws:lambda:region:account:function:SecretsRotation"
```

---

### Option 2: HashiCorp Vault

**Pros:**
- Industry-standard secret management
- Dynamic secrets support
- Excellent audit logging
- Self-hosted option available

**Implementation:**

```javascript
const nodeVault = require('node-vault')();

async function loadFromVault() {
  try {
    const vaultAddr = process.env.VAULT_ADDR || 'http://vault:8200';

    const vault = nodeVault({
      endpoint: vaultAddr,
      token: process.env.VAULT_TOKEN  // Should use AWS IAM auth instead
    });

    const result = await vault.read('secret/data/prod/app-secrets');
    return result.data.data;
  } catch (error) {
    console.error('Vault error:', error);
    throw error;
  }
}
```

---

### Option 3: Improved .env with Encryption (Development Only)

**For development only - NOT for production:**

```javascript
require('dotenv').config();

// Validate required environment variables
const requiredEnvVars = [
  'DATABASE_URL',
  'JWT_SECRET',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY'
];

const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);
if (missingVars.length > 0) {
  throw new Error(`Missing required environment variables: ${missingVars.join(', ')}`);
}

// Ensure we're not using placeholder values in production
if (process.env.NODE_ENV === 'production') {
  const placeholders = Object.entries(process.env)
    .filter(([key, value]) => value.includes('CANARY') || value.includes('placeholder'))
    .map(([key]) => key);

  if (placeholders.length > 0) {
    throw new Error(
      `Production mode cannot use placeholder values. Check: ${placeholders.join(', ')}`
    );
  }
}

console.log(`Running in ${process.env.NODE_ENV} mode`);
```

**Encrypted .env using `dotenv-vault`:**

```bash
# Install dotenv-vault
npm install dotenv-vault

# Encrypt .env
npx dotenv-vault encrypt

# Decrypt at runtime
npx dotenv-vault decrypt
```

---

## Secret Rotation Strategy

### Automated Rotation Plan

```javascript
// rotate-secrets.js
const { SecretsManagerClient, RotateSecretCommand } = require('@aws-sdk/client-secrets-manager');

async function rotateSecret(secretId) {
  const client = new SecretsManagerClient({ region: 'us-east-1' });

  try {
    // 1. Create new version
    const command = new RotateSecretCommand({
      SecretId: secretId,
      RotateImmediately: true
    });

    await client.send(command);
    console.log(`✓ Rotated secret: ${secretId}`);

    // 2. Notify services to refresh (e.g., SNS message)
    // 3. Update database connections
    // 4. Clear application cache
  } catch (error) {
    console.error('Rotation failed:', error);
    throw error;
  }
}

// Rotate database credentials monthly
rotateSecret('prod/app-secrets');
```

**Recommended Rotation Schedule:**

| Secret Type | Rotation Frequency |
|-------------|-------------------|
| Database passwords | 30-90 days |
| API keys | 90-180 days |
| JWT secrets | 90 days |
| Cloud keys | 90 days |
| Certificates | 1 year or earlier |

---

## Secrets Access Controls

### AWS IAM Policy for Secrets Access

