const app = express();

// ============================================================================
// SECRETS MANAGEMENT
// ============================================================================

class SecretsManager {
  constructor(arn, region) {
    this.arn = arn;
    this.region = region;
    this.client = new SecretsManagerClient({ region });
    this.cache = null;
    this.cacheTime = null;
  }

  async getSecret(forceRefresh = false) {
    // Return cached secret if valid
    if (!forceRefresh &&
        this.cache &&
        this.cacheTime &&
        (Date.now() - this.cacheTime < SECRETS_CACHE_TTL)) {
      return this.cache;
    }

    try {
      console.log('[Secrets] Fetching from AWS Secrets Manager...');

      const command = new GetSecretValueCommand({
        SecretId: this.arn
      });

      const response = await this.client.send(command);

      if (!response.SecretString) {
        throw new Error('SecretString not found in response');
      }

      // Parse secret
      const secret = typeof response.SecretString === 'string'
        ? JSON.parse(response.SecretString)
        : response.SecretString;

      // Validate secret structure
      this.validateSecret(secret);

      // Update cache
      this.cache = secret;
      this.cacheTime = Date.now();

      console.log('[Secrets] ✓ Loaded successfully');
      return secret;

    } catch (error) {
      console.error('[Secrets] ✗ Failed to load:', error.message);

      // In development, allow fallback to .env (with warnings)
      if (process.env.NODE_ENV === 'development' && !process.env.FORCE_SECRETS_MANAGER) {
        return this.loadFromEnv();
      }

      throw new Error(`Failed to load secrets: ${error.message}`);
    }
  }

  validateSecret(secret) {
    if (!secret || typeof secret !== 'object') {
      throw new Error('Invalid secret format');
    }

    // Check required secrets
    const missing = REQUIRED_SECRETS.filter(key => !secret[key]);
    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Detect placeholder values (fail in production)
    if (process.env.NODE_ENV === 'production') {
      const placeholders = Object.entries(secret)
        .filter(([key, value]) =>
          typeof value === 'string' && PLACEHOLDER_PATTERNS.some(p => p.test(value))
        )
        .map(([key]) => key);

      if (placeholders.length > 0) {
        throw new Error(
          `Production cannot use placeholder values. Check: ${placeholders.join(', ')}`
        );
      }
    } else if (process.env.NODE_ENV === 'development') {
      // Warn about placeholders in development
      const placeholders = Object.entries(secret)
        .filter(([key, value]) =>
          typeof value === 'string' && PLACEHOLDER_PATTERNS.some(p => p.test(value))
        )
        .map(([key]) => key);

      if (placeholders.length > 0) {
        console.warn(`[Secrets] ⚠ Placeholder values detected: ${placeholders.join(', ')}`);
      }
    }

    return true;
  }

  loadFromEnv() {
    console.warn('[Secrets] ⚠ Falling back to environment variables (development only)');

    const secret = {
      DATABASE_URL: process.env.DATABASE_URL,
      JWT_SECRET: process.env.JWT_SECRET,
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
    };

    this.validateSecret(secret);
    return secret;
  }

  clearCache() {
    console.log('[Secrets] Cache cleared');
    this.cache = null;
    this.cacheTime = null;
  }

  // Safe secret access with logging
  getSecretValue(key) {
    if (!this.cache) {
      throw new Error('Secrets not loaded. Call getSecret() first.');
    }

    const sensitiveKeys = ['DATABASE_URL', 'AWS_SECRET_ACCESS_KEY', 'STRIPE_SECRET_KEY'];
    if (sensitiveKeys.includes(key)) {
      console.log(`[Secrets] Accessing sensitive secret: ${key}`);
    }

    return this.cache[key];
  }
}

// ============================================================================
// SECRETS AUDIT LOGGING
// ============================================================================

class SecretAuditor {
  constructor(secretsManager) {
    this.secretsManager = secretsManager;
    this.accessLog = [];
    this.maxLogSize = 1000;
  }

  logAccess(key, source = 'app') {
    const entry = {
      timestamp: new Date().toISOString(),
      key: this.maskSensitiveKey(key),
      source: source
    };

    this.accessLog.push(entry);

    // Trim log if too large
    if (this.accessLog.length > this.maxLogSize) {
      this.accessLog = this.accessLog.slice(-this.maxLogSize);
    }

    // Warn about frequent access to sensitive keys
    const recentAccess = this.accessLog
      .filter(e => e.key === key && e.source === source)
      .filter(e => Date.now() - new Date(e.timestamp).getTime() < 60000); // Last minute

    if (key === 'DATABASE_URL' && recentAccess.length > 50) {
      console.warn(`[Audit] ⚠ High frequency access to ${key}: ${recentAccess.length}/min`);
    }
  }

  maskSensitiveKey(key) {
    const sensitiveRegex = /secret|password|key|token/i;
    return sensitiveRegex.test(key) ? '***SENSITIVE***' : key;
  }

  getAccessReport(minutes = 60) {
    const since = Date.now() - (minutes * 60 * 1000);

    return this.accessLog
      .filter(e => new Date(e.timestamp).getTime() > since)
      .reduce((acc, entry) => {
        acc[entry.key] = (acc[entry.key] || 0) + 1;
        return acc;
      }, {});
  }
}

