        }
      }),
      writable: false,
      enumerable: false,
      configurable: false
    });

    // Store manager instances for later use
    app.set('secretsManager', secretsManager);
    app.set('auditor', auditor);

    appReady = true;
    console.log('✓ Application initialized successfully');
    console.log(`  Port: ${PORT}`);
