### 🔴 CRITICAL: No Authentication/Authorization

**OWASP Category:** A01:2021 - Broken Access Control  
**CVSS Score:** 9.1 (Critical)

#### Description
The `/users` endpoint exposes sensitive user data (names and emails) without any authentication mechanism. Anyone can access this data by making a simple HTTP request.

#### Vulnerable Code
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

#### Exploit Scenario
```bash
# Anyone can fetch user data
curl http://localhost:3000/users

# Response:
[{"id":1,"name":"Alice","email":"alice@example.com"},...]
```

#### Recommendations

**Option 1: JWT Authentication**
```javascript
const jwt = require('jsonwebtoken');

const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

app.get('/users', authenticate, authorize('admin'), (req, res) => {
  res.json(users);
});
```

**Option 2: API Key Authentication (Simpler)**
```javascript
const authenticate = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];
  if (apiKey !== process.env.API_KEY) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
};
```

**Option 3: OAuth 2.0 / OpenID Connect (Production Recommendation)**
```javascript
const passport = require('passport');
const { OAuth2Strategy } = require('passport-oauth');

passport.use(new OAuth2Strategy({
  authorizationURL: 'https://auth.example.com/oauth/authorize',
  tokenURL: 'https://auth.example.com/oauth/token',
  clientID: process.env.CLIENT_ID,
  clientSecret: process.env.CLIENT_SECRET,
  callbackURL: '/auth/callback'
}, (accessToken, refreshToken, profile, done) => {
  // Verify user and create session
  return done(null, profile);
}));

app.get('/users', passport.authenticate('bearer', { session: false }), (req, res) => {
  res.json(users);
});
```

