### Secrets Loading Implementation

```javascript
/**
 *Secure Configuration Loader
 * Loads secrets from environment variables or AWS Secrets Manager
 */

const AWS = require('aws-sdk');

class Config {
  constructor() {
    this.secrets = {};
  }

  async init() {
    if (process.env.NODE_ENV === 'production') {
      await this.loadFromAWS();
    } else {
      this.loadFromEnv();
    }
    this.validate();
  }

  async loadFromAWS() {
    const region = process.env.AWS_REGION || 'us-east-1';
    const secretsManager = new AWS.SecretsManager({ region });

    try {
      // Fetch all secrets at once (parallel for performance)
      const secrets = await Promise.all([
        secretsManager.getSecretValue({ SecretId: 'app/prod/database' }).promise(),
        secretsManager.getSecretValue({ SecretId: 'app/prod/api-keys' }).promise(),
        secretsManager.getSecretValue({ SecretId: 'app/prod/stripe' }).promise()
      ]);

      // Parse and store
      this.secrets = {
        database: JSON.parse(secrets[0].SecretString),
        apiKeys: JSON.parse(secrets[1].SecretString),
        stripe: JSON.parse(secrets[2].SecretString)
      };

      console.log('✓ Secrets loaded from AWS Secrets Manager');
    } catch (error) {
      console.error('Failed to load secrets from AWS:', error);
      throw error;
    }
  }

  loadFromEnv() {
    // For development, load from .env file
    // Use process.env directly - don't copy to this.secrets
    console.log('✓ Configuration loaded from environment variables');
  }

  validate() {
    const required = process.env.NODE_ENV === 'production' 
      ? ['database.url', 'stripe.secretKey', 'apiKeys.anthropic']
      : [];

    // Check production secrets
    required.forEach(path => {
      const value = path.split('.').reduce((obj, key) => obj?.[key], this.secrets);
      if (!value) {
        throw new Error(`Missing required secret: ${path}`);
      }
    });

    // Verify test credentials in test mode
    if (process.env.NODE_ENV === 'test' || process.env.NODE_ENV === 'development') {
      const hasTestKeys = 
        process.env.DATABASE_URL?.includes('localhost') ||
        process.env.STRIPE_SECRET_KEY?.startsWith('sk_test_');

      if (!hasTestKeys) {
        console.warn('⚠ Production credentials detected in test environment!');
      }
    }
  }

  // Secure getter - never returns all secrets at once
  get(path) {
    if (process.env.NODE_ENV === 'production') {
      return path.split('.').reduce((obj, key) => obj?.[key], this.secrets);
    }
    return process.env[path.toUpperCase()] || process.env[path];
  }

  // Specifically for database connection
  getDatabaseConfig() {
    if (process.env.NODE_ENV === 'production') {
      return {
        connectionString: this.secrets.database.url,
        ssl: { rejectUnauthorized: true }
      };
    }
    return {
      host: process.env.PGHOST,
      port: process.env.PGPORT,
      user: process.env.PGUSER,
      password: process.env.PGPASSWORD,
      database: process.env.PGDATABASE
    };
  }
}

module.exports = new Config();
```

