```javascript
// Install: npm install @aws-sdk/client-secrets-manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretsManager = new SecretsManagerClient({ region: process.env.AWS_REGION });

async function loadSecrets() {
  try {
    const response = await secretsManager.send(
      new GetSecretValueCommand({
        SecretId: process.env.SECRET_ARN || 'myapp/production',
      })
    );

    const secrets = JSON.parse(response.SecretString);

    // Load into process.env
    Object.assign(process.env, secrets);
  } catch (error) {
    console.error('Failed to load secrets from AWS Secrets Manager:', error);
    throw error;
  }
}

// Initialize app after loading secrets
async function startServer() {
