### Recommended Approach: Secrets Manager

Instead of `.env` files in production, consider:

```javascript
// Example using AWS Secrets Manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function loadSecret(secretName) {
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

  const response = await client.send(
    new GetSecretValueCommand({ SecretId: secretName })
  );

  return JSON.parse(response.SecretString);
}

// Initialize app with secrets from secure manager
async function initializeApp() {
  try {
    const secrets = await loadSecret('my-app/production');

    // Use secrets directly in config, not process.env
    const config = {
      database: {
        url: secrets.database_url,
        password: secrets.database_password
      },
      jwt: {
        secret: secrets.jwt_secret
      }
    };

    return config;
  } catch (error) {
    console.error('Failed to load secrets:', error);
    process.exit(1);
  }
}
```

