require('dotenv').config(); // Only for local dev, not production
const AWS = require('aws-sdk');

let cachedSecrets = {};

async function loadSecretsFromManager() {
  // Skip if running locally with .env
  if (process.env.NODE_ENV !== 'production') {
    return {
      databaseUrl: process.env.DATABASE_URL,
      stripeKey: process.env.STRIPE_SECRET_KEY,
      // ... other local env vars
    };
  }

  // Production: fetch from Secrets Manager
  const sm = new AWS.SecretsManager({ region: process.env.AWS_REGION });
  const secretArn = 'arn:aws:secretsmanager:region:account:secret:prod/app-secrets';

  if (cachedSecrets.expiry > Date.now()) {
    return cachedSecrets.data;
  }

  try {
    const result = await sm.getSecretValue({ SecretId: secretArn }).promise();
    const secrets = JSON.parse(result.SecretString);

    // Cache for 5 minutes to reduce API calls
    cachedSecrets = {
      data: secrets,
      expiry: Date.now() + (5 * 60 * 1000)
    };

    return secrets;
  } catch (error) {
    throw new Error(`Failed to load secrets: ${error.message}`);
  }
}

