## 🔒 Complete Secure Secrets Loading Pattern

Here's a production-ready secrets management solution:

```javascript
// config/secrets.js
require('dotenv').config({ path: `.env.${process.env.NODE_ENV || 'development'}` });

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.ttl = 5 * 60 * 1000; // 5 minute cache TTL
    this.useVault = process.env.NODE_ENV === 'production';
  }

  async get(secretName) {
    const cached = this._getCached(secretName);
    if (cached) return cached;

    let secret;

    if (this.useVault) {
      secret = await this._fromVault(secretName);
    } else {
      secret = await this._fromEnv(secretName);
    }

    this._setCache(secretName, secret);
    return secret;
  }

  async _fromVault(secretName) {
    // AWS Secrets Manager implementation
    if (!process.env.SECRETS_PREFIX) {
      throw new Error('SECRETS_PREFIX not configured');
    }

    const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    const response = await client.send(
      new GetSecretValueCommand({ 
        SecretId: `${process.env.SECRETS_PREFIX}/${secretName}`
      })
    );

    return JSON.parse(response.SecretString);
  }

  async _fromEnv(secretName) {
    // Fallback to environment variables for development
    const envVar = secretName.toUpperCase().replace(/-/g, '_');
    const value = process.env[envVar];

    if (!value) {
      throw new Error(`Secret ${secretName} (${envVar}) not found in environment`);
    }

    return value;
  }

  _getCached(key) {
    const entry = this.cache.get(key);
    if (entry && Date.now() - entry.timestamp < this.ttl) {
      return entry.value;
    }
    return null;
  }

  _setCache(key, value) {
    this.cache.set(key, { value, timestamp: Date.now() });
  }

  clearCache() {
    this.cache.clear();
  }
}

module.exports = new SecretsManager();
```

