// config/secrets.js
const AWS = require('aws-sdk');
const { SSM, ParameterType } = require('@aws-sdk/client-ssm');

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.ttl = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(name) {
    // Check cache first
    const cached = this.cache.get(name);
    if (cached && Date.now() - cached.timestamp < this.ttl) {
      return cached.value;
    }

    // Load from environment (fallback for local dev)
    const envValue = process.env[name];
    if (envValue) {
      this.cache.set(name, { value: envValue, timestamp: Date.now() });
      return envValue;
    }

    // Load from AWS Systems Manager Parameter Store (production)
    if (process.env.NODE_ENV === 'production') {
      try {
        const ssm = new SSM({ region: process.env.AWS_REGION || 'us-east-1' });
        const response = await ssm.getParameter({
          Name: `/myapp/${name.toLowerCase()}`,
          Type: ParameterType.SECURE_STRING,
          WithDecryption: true,
        });

        if (response.Parameter?.Value) {
          this.cache.set(name, { value: response.Parameter.Value, timestamp: Date.now() });
          return response.Parameter.Value;
        }
      } catch (error) {
        console.error(`Failed to load secret ${name} from SSM:`, error.message);
      }
    }

    throw new Error(`Secret ${name} not found`);
  }

  // Bulk loading with concurrency
  async loadSecrets(names) {
    const secrets = await Promise.all(
      names.map(name => this.getSecret(name).catch(() => null))
    );

    const result = {};
    names.forEach((name, i) => {
      if (secrets[i]) result[name] = secrets[i];
    });

    return result;
  }
}

module.exports = new SecretsManager();
```

